CREATE TABLE IF NOT EXISTS points (id TEXT PRIMARY KEY, type TEXT NOT NULL, name TEXT NOT NULL, district TEXT NOT NULL, spot TEXT NOT NULL, lat REAL NOT NULL, lng REAL NOT NULL, description TEXT NOT NULL DEFAULT '', sterilized TEXT NOT NULL DEFAULT 'unknown', cats INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, photo TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS checkins (id TEXT PRIMARY KEY, point_id TEXT NOT NULL, created_at TEXT NOT NULL, cats INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS favorites (point_id TEXT PRIMARY KEY, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cats (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
